<?php require_once __DIR__.'/../../app/bootstrap.php';guard();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$q=$p->prepare("SELECT * FROM topup_requests WHERE id=?");$q->execute([$id]);$r=$q->fetch();if($r&&$r['status']==='pending'){$p->prepare("UPDATE topup_requests SET status=?,admin_note=? WHERE id=?")->execute([$status,trim($_POST['note']??''),$id]);if($status==='approved'){credit_wallet($p,(int)$r['user_id'],(int)$r['amount'],'شارژ کیف پول', $id);$q=$p->prepare("SELECT telegram_id FROM users WHERE id=?");$q->execute([$r['user_id']]);$tg=(int)$q->fetchColumn();send_msg($tg,'✅ درخواست شارژ شما تأیید شد.'."\nمبلغ: <b>".money((int)$r['amount']).'</b>');}}}$rows=$p->query("SELECT t.*,u.telegram_id,u.first_name,u.last_name FROM topup_requests t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 100")->fetchAll();?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>شارژ</title><style>body{font-family:Tahoma;background:#f4f8fc}.wrap{max-width:1100px;margin:30px auto}.card{background:#fff;padding:20px;border-radius:18px}select,textarea{padding:8px;width:100%;box-sizing:border-box;margin:4px 0}button{background:#1687d9;color:#fff;border:0;padding:8px 12px;border-radius:8px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #eee}</style><div class=wrap><a href=/admin/index.php>← داشبورد</a><div class=card><h2>💳 درخواست‌های شارژ</h2><table><tr><th>کاربر</th><th>مبلغ</th><th>کد پیگیری</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['telegram_id'])?></td><td><?=money((int)$r['amount'])?></td><td><?=e($r['tracking_code'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=id value=<?=$r['id']?>><select name=status><option value=approved>تأیید</option><option value=rejected>رد</option></select><textarea name=note placeholder="یادداشت"></textarea><button>ثبت</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div>
